import React, { useState, useEffect } from 'react';
import './App.css';
import Filter from './components/Filter';
import EventTable from './components/EventTable';
import axios from 'axios';

function App() {
  const [loading, setLoading] = useState(true);
  const [events, setEvents] = useState([]);
  const [totalEvents, setTotalEvents] = useState(0);
  const [currentPage, setCurrentPage] = useState(1);
  const [pageSize] = useState(10);
  const [filters, setFilters] = useState({
    medication: '',
    adverse_event: '',
    start_date: '',
    end_date: ''
  });
  const [medications, setMedications] = useState([]);
  const [adverseEvents, setAdverseEvents] = useState([]);

  // Fetch dropdown options when component mounts
  useEffect(() => {
    fetchOptions();
  }, []);

  // Fetch events when filters or pagination changes
  useEffect(() => {
    fetchEvents();
  }, [filters, currentPage]);

  const fetchOptions = async () => {
    try {
      const [medicationsRes, adverseEventsRes] = await Promise.all([
        axios.get('/api/medications'),
        axios.get('/api/adverse_events')
      ]);
      setMedications(medicationsRes.data.map(med => ({ value: med, label: med })));
      setAdverseEvents(adverseEventsRes.data.map(event => ({ value: event, label: event })));
    } catch (error) {
      console.error('Error fetching options:', error);
    }
  };

  const fetchEvents = async () => {
    setLoading(true);
    try {
      const params = {
        page: currentPage,
        page_size: pageSize,
        ...filters
      };

      // Remove empty params
      Object.keys(params).forEach(key => 
        params[key] === '' && delete params[key]
      );

      const response = await axios.get('/api/events', { params });
      setEvents(response.data.data);
      setTotalEvents(response.data.total);
      setLoading(false);
    } catch (error) {
      console.error('Error fetching events:', error);
      setLoading(false);
    }
  };

  const handleFilterChange = (newFilters) => {
    setCurrentPage(1); // Reset to first page when filters change
    setFilters(newFilters);
  };

  const handlePageChange = (page) => {
    setCurrentPage(page);
  };

  const handleExportCSV = () => {
    // Build URL with current filters
    const params = new URLSearchParams();
    Object.entries(filters).forEach(([key, value]) => {
      if (value) params.append(key, value);
    });

    // Open export URL in new tab
    window.open(`/api/events/export?${params.toString()}`, '_blank');
  };

  return (
    <div className="app">
      <header className="app-header">
        <div className="container">
          <h1>Drug Adverse Events Dashboard</h1>
        </div>
      </header>

      <main className="container">
        <Filter 
          medications={medications}
          adverseEvents={adverseEvents}
          onFilterChange={handleFilterChange}
          onExportCSV={handleExportCSV}
        />

        <EventTable 
          events={events}
          loading={loading}
          totalEvents={totalEvents}
          currentPage={currentPage}
          pageSize={pageSize}
          onPageChange={handlePageChange}
        />
      </main>

      <footer className="app-footer">
        <div className="container">
          <p>Data source: OpenFDA Adverse Events API</p>
        </div>
      </footer>
    </div>
  );
}

export default App;
